import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { first, lastValueFrom } from 'rxjs';
import { SignupRequestDto } from 'src/app/_models/';
import { User } from 'src/app/_models/user';
import { AuthenticationService } from 'src/app/_services';

@Component({
    selector: 'app-signup',
    templateUrl: './signup.component.html',
    styleUrls: ['./signup.component.css']
})
export class SignupComponent {
    email: string = '';
    username: string = '';
    name: string = '';
    surname: string = '';
    password: string = '';

    isLevel1error: boolean = false;
    level1errorMessage: string = '';
    isLevel0error: boolean = false;
    level0errorMessage: string = '';

    constructor(
        private authService: AuthenticationService,
        private router: Router
    ) {}

    step = 0;

    signup() {
        let user = new User(this.username, this.email, this.name, this.surname);

        let signupRequestDto: SignupRequestDto = new SignupRequestDto(
            user,
            this.password
        );
        console.log(signupRequestDto);

        this.authService
            .signup(signupRequestDto)
            .subscribe({
                next: (response) => {
                    console.log(response);
					alert('Successfully signed up');
                    this.router.navigate(['/login']);
                },
                error: (err) => {
                    console.log(err);
                    alert('Error while signing up: ' + err);
                }
            });
    }

    next() {
        if (!this.validateStep()) {
            alert('Please fill in all the fields correctly');
            return;
        }

        if (this.step == 2) {
            this.signup();
            return;
        }

        this.step++;
    }

    back() {
        if (this.step > 0) {
            this.step--;
        }
    }

    validateStep() {
        return !this.isLevel0error && !this.isLevel1error;
    }

    checkUsername($event: any) {
        const alphanumericRegex: RegExp = /^[a-zA-Z0-9]+$/;
        if (!alphanumericRegex.test(this.username)) {
            this.isLevel1error = true;
            this.level1errorMessage = 'Invalid username';
            return;
        }

        this.isLevel1error = false;

        this.authService.isUsernameAvailable(this.username).subscribe({
            next: (response) => {
                console.log(response);
                if (!response) {
                    this.isLevel1error = true;
                    this.level1errorMessage = 'Username already in use';
                }
            },
            error: (err) => {
                console.log(err);
            }
        });
    }

    checkEmail($event: any) {
        const emailRegex: RegExp = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(this.email)) {
            this.isLevel0error = true;
            this.level0errorMessage = 'Invalid email';
            return;
        }

        this.isLevel0error = false;

        this.authService.isEmailAvailable(this.email).subscribe({
            next: (response) => {
                console.log(response);
                if (!response) {
                    this.isLevel0error = true;
                    this.level0errorMessage = 'Email already in use';
                }
            },
            error: (err) => {
                console.log(err);
                this.isLevel0error = true;
                this.level0errorMessage = 'Error checking email';
            }
        });
    }

    checkName($event: any) {
        const alphanumericRegex: RegExp = /^[a-zA-Z0-9]+$/;

        if (!alphanumericRegex.test(this.name)) {
            this.isLevel0error = true;
            this.level0errorMessage = 'Invalid name';
            return;
        }

        this.isLevel0error = false;
    }

    checkSurname($event: any) {
        const alphanumericRegex: RegExp = /^[a-zA-Z0-9]+$/;

        if (!alphanumericRegex.test(this.surname)) {
            this.isLevel1error = true;
            this.level1errorMessage = 'Invalid surname';
            return;
        }

        this.isLevel1error = false;
    }

    checkPassword($event: any) {
        if (this.password.length < 4) {
            this.isLevel1error = true;
            this.level1errorMessage =
                'Password must be at least 8 characters long';
            return;
        }

        this.isLevel1error = false;
    }
}
<div class="container d-flex flex-column align-items-center">
    <!-- logo svg -->
    <div class="d-flex flex-column align-items-center h-100 mainPage">
        <br /><br />
        <img src="assets/img/logo.svg" alt="logo" class="logo" />
        <br /><br />
        <input
            *ngIf="step == 0"
            class="default-input"
            type="text"
            [(ngModel)]="email"
            (ngModelChange)="checkEmail($event)"
            placeholder="Email"
        />
        <input
            *ngIf="step == 1"
            class="default-input"
            type="text"
            [(ngModel)]="name"
            (ngModelChange)="checkName($event)"
            placeholder="Name"
        />
        <!-- error for email not available -->
        <label *ngIf="isLevel0error" class="error availabilityError">{{
            level0errorMessage
        }}</label>
        <br /><br />
        <input
            *ngIf="step == 0"
            class="default-input"
            type="text"
            [(ngModel)]="username"
            (ngModelChange)="checkUsername($event)"
            placeholder="Username"
        />
        <input
            *ngIf="step == 1"
            class="default-input"
            type="text"
            [(ngModel)]="surname"
            (ngModelChange)="checkSurname($event)"
            placeholder="Surname"
        />
        <input
            *ngIf="step == 2"
            class="default-input"
            type="password"
            [(ngModel)]="password"
            (ngModelChange)="checkPassword($event)"
            placeholder="password"
        />
        <!-- error for username not available -->
        <label *ngIf="isLevel1error" class="error availabilityError">{{
            level1errorMessage
        }}</label>
        <br /><br />
        <div class="row justify-content-between w-100">
            <button
                *ngIf="step != 0"
                class="default-button short-button invert-button"
                (click)="back()"
            >
                Back
            </button>
            <button
                class="default-button"
                [ngClass]="{ 'short-button': step != 0 }"
                (click)="next()"
            >
                {{ step == 0 ? 'Sign Up' : 'Next' }}
            </button>
        </div>
        <br /><br /><br /><br />
        <a *ngIf="step == 0" class="default-link" routerLink="/login"
            >Already a User? Login</a
        >
    </div>
</div>
